import{_ as e,o as a,c as o,a2 as n}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"State","description":"","frontmatter":{},"headers":[],"relativePath":"components/state.md","filePath":"components/state.md"}'),r={name:"components/state.md"};function d(i,t,s,h,c,l){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h1><p>State is what a place shows when it is empty, loading or has failed.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it in the container that would hold the content, such as a <a href="./block">Block</a> in a panel; a notice about content that is shown is a <a href="./banner">Banner</a>. Write one sentence, at most one note and one action. A failure takes <code>tone=&quot;error&quot;</code>; loading takes <code>loading</code>, which shows a <a href="./spinner">Spinner</a> with the sentence.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code></td><td>required</td><td>The sentence</td></tr><tr><td><code>note</code></td><td></td><td>One sentence under it</td></tr><tr><td><code>tone</code></td><td></td><td><code>error</code> for a failure</td></tr><tr><td><code>loading</code></td><td><code>false</code></td><td>Shows a Spinner with the sentence</td></tr><tr><td><code>actions</code></td><td></td><td>One action (a snippet)</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>No padding: the padding of its container applies. The sentence (body, in the text color, red-ink for a failure) and the note (a muted caption) are at the start, trimmed only at the edge of the container; the action is at the end of its row, as in <a href="./actions">Actions</a>, with a button&#39;s height. The three are gap-sm apart. It has no picture and no heading.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/state/" title="State" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/state/" target="_blank" rel="noopener">State</a></figcaption></figure>',10)])])}const f=e(r,[["render",d]]);export{u as __pageData,f as default};
